solution.exercise.cpp:
#include "exercise.h"
#include <ctype.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int hamming_distance(const char *a, const char *b) {
    int n = 0;
    while (*a && *b)
        n += *a++ != *b++;
    return n;
}

tests.test_exercise.cpp:
#include "exercise.h"
#include <assert.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static bool positive(int x) { return x > 0; }
static bool bstring(const void *p) { return (*(const char *const *)p)[0] == 98; }
static void string_length(const void *p, void *out) {
    *(size_t *)out = strlen(*(const char *const *)p);
}
int main(void) {
    assert(hamming_distance("GAGCCTACTAACGGGAT", "CATCGTAATGACGGCCT") == 7);
    assert(hamming_distance("", "") == 0);
    assert(hamming_distance("A", "A") == 0);
    assert(hamming_distance("", "") == 0);
    assert(hamming_distance("GGACTGA", "GGACTGA") == 0);
    assert(hamming_distance("ACT", "GGA") == 3);
    assert(hamming_distance("GGACGGATTCTGACCTGGACTAATTTTGGGG",
                            "AGGACGGATTCTGACCTGGACTAATTTTGGGG") == 19);
    assert(hamming_distance("GGACG", "GGTCG") == 1);
    assert(hamming_distance("ACCAGGG", "ACTATGG") == 2);
    assert(hamming_distance("AAACTAGGGG", "AGGCTAGCGGTAGGAC") == 3);
    assert(hamming_distance("GACTACGGACAGGGTAGGGAAT", "GACATCGCACACC") == 5);
    return 0;
}
